PYTHONDONTWRITEBYTECODE=1 .venv/bin/python -c 'import itertools,re; from pathlib import Path; from jinja2 import Environment; from triggarr.search.outcome import CycleTally,cycle_view; e=Environment(autoescape=True); e.filters.update(exact_time=lambda x:"time",relative_time=lambda x:"ago"); t=e.from_string(Path("triggarr/templates/partials/cycle_grade.html").read_text()); count=0
for accepted,failed,malformed,unevaluated,fetch in itertools.product([0,1],[0,1],[0,1,3],[False,True],[False,True]):
 c=CycleTally(accepted=accepted)
 if failed: c.record_failed("HTTP 500")
 if malformed: c.record_malformed("missing",malformed)
 if unevaluated: c.mark_unevaluated("cutoff","tag missing <script>")
 if fetch: c.record_fetch_failure("HTTP 503")
 v=cycle_view(c.to_record(active_queues=["missing","cutoff"],finished_at="2026-10-22T00:00:00Z"),"Radarr"); html=t.render(app={"last_cycle":v,"app_label":"Radarr"}); match=re.search(r"<summary[^>]*>(.*?)</summary>",html)
 if v["has_detail"]:
  label=match.group(1); expected="failure reason" if failed or fetch else "detail" if unevaluated else "skipped record"; assert expected in label,(v,label,expected)
 else: assert match is None
 assert "<script>" not in html
 count+=1
print(str(count)+" generated normal-write template cases passed")'
